INSIDE_FUNCTION ! { # [doc = " Collects all macro invocations reachable at this time in this AST fragment, and replace"] # [doc = " them with \"placeholders\" - dummy macro invocations with specially crafted `NodeId`s."] # [doc = " Then call into resolver that builds a skeleton (\"reduced graph\") of the fragment and"] # [doc = " prepares data for resolving paths of macro invocations."] fn collect_invocations (& mut self , mut fragment : AstFragment , extra_placeholders : & [NodeId] ,) -> (AstFragment , Vec < (Invocation , Option < Arc < dyn SyntaxExtensionTrait >>) >) { self . cx . resolver . resolve_dollar_crates () ; let mut invocations = { let mut collector = CollectorSpecial ! ('a , 'b , DRT) { cx : self . cx , invocations : Vec :: new () , monotonic : self . monotonic , } ; fragment . mut_visit_with (& mut collector) ; add_placeholders_to_fragment (& mut fragment , extra_placeholders) ; collector . invocations } ; if self . monotonic { self . cx . resolver . visit_ast_fragment_with_placeholders (self . cx . current_expansion . id , & fragment) ; if self . cx . sess . opts . incremental . is_some () { for (invoc , _) in invocations . iter_mut () { let expn_id = invoc . expansion_data . id ; let parent_def = self . cx . resolver . invocation_parent (expn_id) ; let span = invoc . span_mut () ; * span = span . with_parent (Some (parent_def)) ; } } } (fragment , invocations) } }